function () {
  var KEY = 'fe:consent:v1';
  var CURRENT_V = '2026-06-16';
  var COUNTER = 107136069;
  // Local browser acceptance must not create real Metrika visits or ad requests.
  // Attribution/consent and our same-origin collectors remain available.
  var localHostname = (window.location.hostname || '').toLowerCase();
  var LOCAL_DEVELOPMENT = localHostname === 'localhost' || localHostname === '127.0.0.1' || localHostname === '[::1]' || localHostname === '::1';

  // --- URL hygiene: выполняется всегда, до любых хитов ---
  // Официальные метки Метрики (from, Openstat) нельзя вырезать до первого hit:
  // https://yandex.ru/support/metrica/ru/general/source-tags
  var STRIP_ALWAYS = ['ybaip', 'clid', '_ga', 'ref', 'ref_src', 'source', 'mc_cid', 'mc_eid', 'igshid'];
  var ATTRIBUTION = ['yclid', 'ysclid', 'gclid', 'fbclid', 'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'utm_referrer', 'etext'];
  var STRIP_AFTER_HIT = ATTRIBUTION.concat(['from', '_openstat', 'openstat', 'yandex_referrer']);
  // Приложение ChatGPT / Perplexity часто шлёт только utm_source, без Referer.
  // Штатная замена referer — utm_referrer (отчёт «Сайты»).
  var AI_UTM_REFERRER = {
    'chatgpt.com': 'https://chatgpt.com/',
    'openai': 'https://chatgpt.com/',
    'chat.openai.com': 'https://chatgpt.com/',
    'perplexity': 'https://www.perplexity.ai/',
    'perplexity.ai': 'https://www.perplexity.ai/'
  };
  // Часть «меток» совпадает с рабочими параметрами страниц: у калькуляторов
  // from/to — это годы периода. Вырезать их — значит ломать любую
  // расшаренную ссылку, поэтому на таких путях они неприкосновенны.
  var FUNCTIONAL_PARAMS = [
    { prefix: '/calculator', keep: ['from', 'to'] },
  ];
  function stripParams(search, names) {
    if (!search || search.length <= 1) return search || '';
    var path = window.location.pathname;
    var keep = [];
    for (var f = 0; f < FUNCTIONAL_PARAMS.length; f++) {
      if (path.indexOf(FUNCTIONAL_PARAMS[f].prefix) === 0) {
        keep = keep.concat(FUNCTIONAL_PARAMS[f].keep);
      }
    }
    var params = new URLSearchParams(search);
    var changed = false;
    for (var i = 0; i < names.length; i++) {
      if (keep.indexOf(names[i]) !== -1) continue;
      if (params.has(names[i])) { params.delete(names[i]); changed = true; }
    }
    if (!changed) return search;
    var rest = params.toString();
    return rest ? '?' + rest : '';
  }

  function pickAttr(params, name) {
    try { return params.get(name) || ''; } catch { return ''; }
  }
  function attrsFromSearch(raw) {
    var out = {};
    try {
      var p = new URLSearchParams(raw || '');
      for (var i = 0; i < ATTRIBUTION.length; i++) {
        var v = pickAttr(p, ATTRIBUTION[i]);
        if (v) out[ATTRIBUTION[i]] = v;
      }
    } catch { /* ignore */ }
    return out;
  }

  var search = window.location.search;
  var hitSearch = stripParams(search, STRIP_ALWAYS);
  try {
    var hitParams = new URLSearchParams(hitSearch.charAt(0) === '?' ? hitSearch.slice(1) : hitSearch);
    var fromRef = {};
    try { fromRef = attrsFromSearch(new URL(document.referrer).search); } catch { /* нет referrer */ }
    var fromStore = {};
    try { fromStore = attrsFromSearch(sessionStorage.getItem('fe:attr:q') || ''); } catch { /* нет store */ }
    var fromCookie = {};
    try {
      var cm = document.cookie.match(/(?:^|; )fe_attr=([^;]*)/);
      if (cm) fromCookie = attrsFromSearch('?' + decodeURIComponent(cm[1].replace(/\+/g, ' ')));
    } catch { /* нет куки */ }
    for (var a = 0; a < ATTRIBUTION.length; a++) {
      var key = ATTRIBUTION[a];
      if (!hitParams.get(key) && fromRef[key]) hitParams.set(key, fromRef[key]);
      if (!hitParams.get(key) && fromStore[key]) hitParams.set(key, fromStore[key]);
      if (!hitParams.get(key) && fromCookie[key]) hitParams.set(key, fromCookie[key]);
    }
    try {
      if (!hitParams.get('utm_referrer')) {
        var us = (hitParams.get('utm_source') || '').toLowerCase();
        var aiRef = AI_UTM_REFERRER[us];
        var docRef = document.referrer || '';
        var ownRef = false;
        if (docRef) {
          try {
            var host = (location.hostname || '').replace(/^www\./, '');
            var apex = host.replace(/^ru\./, '');
            var rh = new URL(docRef).hostname.replace(/^www\./, '');
            ownRef = rh === host || rh === apex || rh === 'ru.' + apex;
          } catch { ownRef = false; }
        }
        if (aiRef && (!docRef || ownRef)) hitParams.set('utm_referrer', aiRef);
      }
    } catch { /* ignore */ }
    try { sessionStorage.removeItem('fe:attr:q'); } catch { /* ignore */ }
    var merged = hitParams.toString();
    hitSearch = merged ? '?' + merged : '';
    try { window.__feAttr = attrsFromSearch(hitSearch); } catch { window.__feAttr = {}; }
  } catch { /* ignore */ }
  var displaySearch = stripParams(hitSearch, STRIP_AFTER_HIT);
  var hitPath = window.location.pathname + hitSearch + window.location.hash;
  var cleanPath = window.location.pathname + displaySearch + window.location.hash;

  function firstReferer() {
    var stamped = '';
    try { stamped = new URLSearchParams(hitSearch).get('utm_referrer') || new URLSearchParams(search).get('utm_referrer') || ''; } catch { stamped = ''; }
    var ref = document.referrer || '';
    try {
      var host = (location.hostname || '').replace(/^www\./, '');
      var apex = host.replace(/^ru\./, '');
      if (ref) {
        var rh = new URL(ref).hostname.replace(/^www\./, '');
        if (rh === host || rh === apex || rh === 'ru.' + apex) ref = stamped;
      } else {
        ref = stamped;
      }
    } catch {
      if (!ref) ref = stamped;
    }
    return ref;
  }

  var loaded = { analytics: false, ads: false };

  // --- Гейт рекламы: запрос объявления только за живого человека ---
  //
  // Инцидент 2026-08-27..09-03 (данные Партнёрки): запросы рекламы выросли
  // 220 → 4291/день, показы остались ~150–250, fill 97% → 11,5%. Разбивка по
  // гео/браузеру: «Москва» с fill 21% — это YandexBot (город
  // «Moscow (Tsentralnyy administrativnyy okrug)», device_type=bot), США и
  // Сингапур — скрейперы на Chrome-UA. У всех живых браузеров (Safari, Edge,
  // Firefox, YandexBrowser, MobileSafari) fill остался 100%.
  // Робот грузит consent.js на SSR-страницах и просит объявление, которое
  // никогда не покажет. Для РСЯ это нераспроданный инвентарь и приговор
  // качеству площадки (ставки CPM считаются по конверсионности трафика).
  //
  // Правило: рекламу просим после первого доверенного события ввода
  // (isTrusted), а явных роботов не пускаем вовсе. Замер по behavior_events:
  // 96,6% сессий реальных устройств оставляют след ввода, боты — 0%.
  var BOT_UA_RE = /bot|spider|crawl|slurp|headless|phantom|selenium|webdriver|puppeteer|playwright|python-requests|python\/|aiohttp|httpx|curl\/|wget\/|go-http-client|okhttp|java\/|libwww|scrapy|feedfetcher|facebookexternalhit|preview|lighthouse|pagespeed|gtmetrix|yandexmetrika|yandexdirect/i;

  function looksLikeRobot() {
    try {
      if (navigator.webdriver === true) return true;
      if (BOT_UA_RE.test(navigator.userAgent || '')) return true;
    } catch { /* агент недоступен — решаем по вводу */ }
    return false;
  }

  // Скролл включён: на мобильных это первый жест чтения; тач/мышь/клавиатура
  // покрывают остальные случаи. Синтетические события (isTrusted=false)
  // не считаются — ими headless имитирует человека.
  var HUMAN_EVENTS = ['pointerdown', 'pointermove', 'touchstart', 'wheel', 'scroll', 'keydown'];
  var HUMAN_OPTS = { passive: true, capture: true };

  function onFirstHumanSignal(cb) {
    if (looksLikeRobot()) return null;
    var fired = false;
    function fire(e) {
      if (fired) return;
      if (e && e.isTrusted === false) return;
      fired = true;
      for (var i = 0; i < HUMAN_EVENTS.length; i++) {
        window.removeEventListener(HUMAN_EVENTS[i], fire, HUMAN_OPTS);
      }
      cb();
    }
    for (var j = 0; j < HUMAN_EVENTS.length; j++) {
      window.addEventListener(HUMAN_EVENTS[j], fire, HUMAN_OPTS);
    }
    return fire;
  }

  var METRIKA_SRC = 'https://mc.yandex.ru/metrika/tag.js?id=' + COUNTER;

  // Очередь ym() — официальный сниппет Метрики: все вызовы (init, hit, цели
  // reachGoal из приложения) копятся в ym.a и разбираются tag.js при загрузке,
  // поэтому отложенный скрипт не теряет ни одного события.
  function installMetrikaStub() {
    window.ym = window.ym || function () { (window.ym.a = window.ym.a || []).push(arguments); };
    window.ym.l = window.ym.l || (1 * new Date());
  }

  function injectMetrikaScript() {
    if (LOCAL_DEVELOPMENT) return;
    for (var j = 0; j < document.scripts.length; j++) {
      if (document.scripts[j].src === METRIKA_SRC) return;
    }
    var k = document.createElement('script');
    var a = document.getElementsByTagName('script')[0];
    k.async = true;
    k.src = METRIKA_SRC;
    // Низкий приоритет: разбор tag.js + Вебвизор не должен делить канал и
    // main thread с первым кадром приложения.
    try { k.fetchPriority = 'low'; } catch { /* старые браузеры */ }
    if (a && a.parentNode) a.parentNode.insertBefore(k, a);
    else document.head.appendChild(k);
  }

  // tag.js (~250 КБ + Вебвизор) — самая тяжёлая задача на main thread после
  // гидратации. Хит уже стоит в очереди ym(), сам скрипт подключаем, когда
  // браузер простаивает (timeout — чтобы визит не потерялся, если страница так
  // и не стала idle). Явный клик по баннеру и проверка счётчика в интерфейсе
  // Метрики (UA YandexMetrika) — сразу.
  function scheduleMetrikaScript(immediate) {
    var checker = false;
    try { checker = /YandexMetrika/i.test(navigator.userAgent || ''); } catch { checker = false; }
    if (immediate || checker) {
      injectMetrikaScript();
      return;
    }
    var run = function () { injectMetrikaScript(); };
    if (typeof window.requestIdleCallback === 'function') window.requestIdleCallback(run, { timeout: 2000 });
    else setTimeout(run, 1200);
  }

  function loadMetrika(immediate) {
    if (LOCAL_DEVELOPMENT) return;
    if (loaded.analytics) return;
    loaded.analytics = true;
    installMetrikaStub();
    // Webvisor 2 + form analytics: triggerEvent — JS-события в Webvisor;
    // childIframe — записи внутри embed-виджета; trackHash — deeplink-якоря.
    window.ym(COUNTER, 'init', {
      defer: true,
      webvisor: true,
      clickmap: true,
      accurateTrackBounce: true,
      trackLinks: true,
      trackHash: true,
      triggerEvent: true,
      childIframe: true
    });
    window.ym(COUNTER, 'hit', hitPath, { title: document.title, referer: firstReferer() });
    if (displaySearch !== search && typeof history !== 'undefined' && typeof history.replaceState === 'function') {
      try { history.replaceState(history.state, '', cleanPath); } catch { /* ignore */ }
    }
    scheduleMetrikaScript(immediate);
  }

  function loadAds() {
    if (LOCAL_DEVELOPMENT) return;
    if (loaded.ads) return;
    loaded.ads = true;
    // Очередь yaContextCb наполняется компонентом YandexRSY.jsx независимо
    // от согласия; context.js при загрузке разбирает её и рендерит блоки.
    window.yaContextCb = window.yaContextCb || [];
    var s = document.createElement('script');
    s.src = 'https://yandex.ru/ads/system/context.js';
    s.async = true;
    document.head.appendChild(s);
  }

  // Метрика: хит в очереди на window.load (весь трафик; роботов фильтрует сама),
  // tag.js — на idle (scheduleMetrikaScript).
  // РСЯ — только по сигналу человека. Флаг для тестов и отладки.
  window.__feAdsGate = { requested: false, armed: false, robot: false, signal: null };

  function armAdsGate(explicitHuman) {
    if (LOCAL_DEVELOPMENT) return;
    if (loaded.ads) return;
    // Клик по баннеру согласия — уже доверенный ввод: ждать второго жеста
    // незачем.
    if (explicitHuman) {
      window.__feAdsGate.armed = true;
      window.__feAdsGate.requested = true;
      loadAds();
      return;
    }
    if (window.__feAdsGate.armed) return;
    window.__feAdsGate.armed = true;
    window.__feAdsGate.robot = looksLikeRobot();
    if (window.__feAdsGate.robot) return;
    // Ссылка на обработчик открыта для тестов: в jsdom у любого
    // dispatchEvent isTrusted=false, живой ввод браузера так не воспроизвести.
    window.__feAdsGate.signal = onFirstHumanSignal(function () {
      window.__feAdsGate.requested = true;
      loadAds();
    });
  }

  window.__feApplyConsent = function (consent, opts) {
    if (!consent) return;
    if (consent.analytics) loadMetrika(Boolean(opts && opts.explicit));
    if (consent.ads) armAdsGate(Boolean(opts && opts.explicit));
  };

  // Подразумеваемое согласие: грузим трекеры по умолчанию. Уважаем только
  // явный отказ в рамках ТЕКУЩЕЙ редакции политики (rec.v === CURRENT_V).
  // На первом заходе не конкурируем с CSS/JS приложения — ждём window.load.
  var IMPLIED = { analytics: true, ads: true };
  var rec = null;
  try {
    var raw = window.localStorage.getItem(KEY);
    if (raw) rec = JSON.parse(raw);
  } catch { rec = null; }
  var consentToApply = rec && rec.v === CURRENT_V ? rec : IMPLIED;
  function applyNow() {
    try { window.__feApplyConsent(consentToApply); }
    catch { window.__feApplyConsent(IMPLIED); }
  }
  if (document.readyState === 'complete') applyNow();
  else window.addEventListener('load', applyNow, { once: true });
}

function () {
  'use strict';
  var root = document.getElementById('seo-ticker');
  if (!root || !window.fetch) return;

  var en = (document.documentElement.lang || 'ru').slice(0, 2) === 'en';
  var lane = root.getAttribute('data-lane') || 'world';

  var META = {
    'usd-rub-live': { l: 'USD/RUB', p: 'usd-rub', d: 2 },
    'eur-rub-live': { l: 'EUR/RUB', p: 'eur-rub', d: 2 },
    'cny-rub-live': { l: 'CNY/RUB', p: 'cny-rub', d: 2 },
    'eur-usd': { l: 'EUR/USD', p: 'eur-usd', d: 2 },
    'gbp-usd': { l: 'GBP/USD', p: 'gbp-usd', d: 2 },
    'usd-cny': { l: 'USD/CNY', p: 'usd-cny', d: 2 },
    'btc-usd': { l: 'BTC/USD', p: 'btc-usd', d: 0 },
    'brent': { l: 'Brent', p: 'brent', d: 2 },
    'gold-rub-live': { l: en ? 'Gold ₽/g' : 'Золото ₽/г', p: 'gold-price', d: 0 }
  };
  var SRC = en ? { market: 'exchange', cb: 'central bank' } : { market: 'биржа', cb: 'ЦБ' };
  var tag = en ? 'en-US' : 'ru-RU';

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  }
  function num(v, d) {
    return v.toLocaleString(tag, { minimumFractionDigits: d, maximumFractionDigits: d });
  }
  function srcKind(s) {
    s = String(s || '');
    if (/moex|мосбирж/i.test(s)) return 'market';
    if (/cbr|банк россии|цб/i.test(s)) return 'cb';
    return null;
  }

  function cell(s) {
    var m = META[s.code];
    if (!m || !(s.price > 0)) return '';
    var html = '<span class="seo-tk-l">' + esc(m.l) + '</span><b class="seo-tk-v">' + esc(num(s.price, m.d)) + '</b>';
    var kind = srcKind(s.source);
    if (kind) html += '<span class="seo-tk-s">' + esc(SRC[kind]) + '</span>';
    var pct = s.change_pct;
    if (typeof pct === 'number' && Math.abs(pct) >= 0.005) {
      var up = pct > 0;
      var body = (up ? '+' : '−') + num(Math.abs(pct), 2) + '%';
      html += '<span class="seo-tk-d ' + (up ? 'seo-tk-up' : 'seo-tk-down') + '"><i aria-hidden="true">' +
        (up ? '↗' : '↘') + '</i>' + esc(body) + '</span>';
    }
    return '<a class="seo-tk" href="/russia/indicator/' + m.p + '">' + html + '</a>';
  }

  function render(data) {
    var rows = (data && data.snapshots) || [];
    var items = rows.map(cell).filter(Boolean).join('');
    if (!items) { root.hidden = true; return; }
    // Две одинаковые половины дают бесшовную петлю: анимация сдвигает дорожку ровно на половину.
    root.innerHTML = '<div class="seo-tk-view"><div class="seo-tk-track">' +
      '<div class="seo-tk-set">' + items + '</div>' +
      '<div class="seo-tk-set" aria-hidden="true">' + items.replace(/<a /g, '<a tabindex="-1" ') + '</div></div></div>';
    var track = root.firstChild.firstChild;
    var half = track.firstChild.getBoundingClientRect().width;
    // Скорость примерно 40 px/с: читаемо, но не отвлекает.
    if (half > 0) track.style.setProperty('--seo-tk-run', Math.max(20, Math.round(half / 40)) + 's');
  }

  fetch('/api/v1/ticker/live?lane=' + encodeURIComponent(lane), { cache: 'no-store', credentials: 'same-origin' })
    .then(function (r) { if (!r.ok) throw new Error('ticker ' + r.status); return r.json(); })
    .then(render)
    .catch(function () { root.hidden = true; });
}

caches.open(CACHE)
      // cache: 'reload' — офлайн-страница всегда свежая, не из HTTP-кэша браузера.
      .then

caches.open(CACHE)
      // cache: 'reload' — офлайн-страница всегда свежая, не из HTTP-кэша браузера.
      .then((cache) => Promise.all(PRECACHE.map((url) => cache.add(new Request(url, { cache: 'reload' })))))
      .then(() => self.skipWaiting())
      // Не удалось положить офлайн-страницу — всё равно ставимся: без неё нет только запасного экрана.
